public infix fun <R> ULongArray.zip(other: Iterable<R>): List<Pair<ULong, R>> {
    val arraySize = size
    val list = ArrayList<Pair<ULong, R>>()
    var i = 0
    for (element in other) {
        if (i >= arraySize) break
        list.add(Pair(this[i], element))
        i++
    }
    return list
}
