private fun ULongArray.flipRange(fromIndex: Int, toIndex: Int) {
    var i = fromIndex
    while (i < toIndex) { val x = storage[i]; storage[i] = (x xor Long.MIN_VALUE); i++ }
}
public fun ULongArray.sort(fromIndex: Int, toIndex: Int) {
    checkArrayRangeIndexes(fromIndex, toIndex, size)
    flipRange(fromIndex, toIndex)
    storage.sort(fromIndex, toIndex)
    flipRange(fromIndex, toIndex)
}
